      @('Negative control: an upgrade of one layer changes what every layer admits and not only its',
        'own. TLC must report TheOtherLayersKeepTheirOrdinaryRules violated.')),
    @('UpgradeRulesApplyToEveryLayerBody', 'upgrade-rules-apply-to-every-layer', 'INVARIANTS', 'TheOtherLayersKeepTheirOrdinaryRules', $layered.TwoLayersSafe, 0, 0, 0, 0, $true, $false,
      @('Negative control: an upgrade with a body of one layer changes what every layer admits and',
        'not only its own. TLC must report TheOtherLayersKeepTheirOrdinaryRules violated.'), 0, 0, 0, $true, 0, 1)
)
foreach ($c in $controls) {
    $pair = One $c[2] $c[3]
    $leases = if ($c.Count -gt 12) { $c[12] } else { 0 }
    $slots = if ($c.Count -gt 13) { $c[13] } else { 0 }
    $listings = if ($c.Count -gt 14) { $c[14] } else { 0 }
    $txn = if ($c.Count -gt 15) { $c[15] } else { $false }
    $discoveries = if ($c.Count -gt 16) { $c[16] } else { 0 }
    $upSteps = if ($c.Count -gt 17) { $c[17] } else { 0 }
    $unlogged = if ($c.Count -gt 18) { $c[18] } else { $false }
    $text = Cfg $c[4] $c[5] $c[6] $c[7] $c[8] $c[1] $c[9] $c[10] $pair[0] $pair[1] $leases $slots $listings $txn $discoveries $upSteps $unlogged
    Write-Cfg "Coordination-Control-$($c[0]).cfg" (Header $c[11]) $text
}

